# Compile once per process
_src_cuda = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Wavefront shuffle reduction (warpSize is 64 on AMD)
__device__ __forceinline__ float wave_reduce_sum(float v) {
    for (int offset = warpSize / 2; offset > 0; offset >>= 1) {
        v += __shfl_down(v, offset, warpSize);
    }
    return v;
}

// One block computes one output row (dot product of length K)
// K must be divisible by 4 (true for this benchmark).
extern "C" __global__ __launch_bounds__(256)
void gemv_fp32_vec4_kernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int K4) {
    int row = (int)blockIdx.x;
    int tid = (int)threadIdx.x;

    const float4* __restrict__ A4 = reinterpret_cast<const float4*>(A + ((size_t)row) * ((size_t)K4) * 4);
    const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);

    float s0 = 0.0f, s1 = 0.0f, s2 = 0.0f, s3 = 0.0f;

    for (int i = tid; i < K4; i += (int)blockDim.x) {
        float4 a = A4[i];
        float4 b = B4[i];
        s0 = fmaf(a.x, b.x, s0);
        s1 = fmaf(a.y, b.y, s1);
        s2 = fmaf(a.z, b.z, s2);
        s3 = fmaf(a.w, b.w, s3);
    }

    float sum = (s0 + s1) + (s2 + s3);

    // Reduce within each wavefront
    sum = wave_reduce_sum(sum);

    // 256 threads = 4 wavefronts (warpSize=64)
    __shared__ float partial[4];
    if ((tid & (warpSize - 1)) == 0) {
        partial[tid / warpSize] = sum;
    }
    __syncthreads();

    // Final reduce by first wavefront
    float block_sum = 0.0f;
    if (tid < 4) block_sum = partial[tid];
    if (tid < warpSize) {
        block_sum = wave_reduce_sum(block_sum);
        if (tid == 0) {
            C[row] = block_sum;
        }
    }
}

